contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address depositor, address ownerActor) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        vm.assume(depositor != address(0) && ownerActor != address(0));

        // fund and drive a deposit into c
        vm.deal(depositor, amount);
        vm.prank(depositor);
        c.deposit{value: amount}();
        require(address(c).balance == amount);

        // the owner (deployer of c in setUp) calls withdrawAll
        vm.prank(address(this));
        try c.withdrawAll() {
            // General rule: after withdrawAll, the whole balance has left the contract.
            assertTrue(address(c).balance == 0);
        } catch {
            assertTrue(false);
        }
    }

    receive() external payable {}
}

