pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, type(uint128).max);
        address owner = c.owner(); // the test contract (deployer of C), which has receive()
        vm.deal(address(c), amount);
        uint256 ownerBefore = owner.balance;

        vm.prank(owner);
        c.withdrawAll();

        // Rule: withdrawAll pays the caller exactly the contract's prior balance.
        assertTrue(owner.balance == ownerBefore + amount && address(c).balance == 0);
    }
}

