pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        // keep the fuzzed deposit amount in an admissible, wide domain
        amount = bound(amount, 1, 2 ** 120);

        // fund the owner (this contract, which is c's owner by construction)
        vm.deal(address(this), amount + 1 ether);

        // deposit into c through its payable receive
        c.deposit
        {value: amount}();

        uint256 balBefore = address(c).balance;

        // drive the buggy/correct boundary entry
        vm.prank(address(this));
        try c.withdrawAll() {
            // rule: after withdrawAll, the contract holds no ether for any admissible amount
            assertTrue(address(c).balance == 0 && balBefore == amount, "withdrawAll must empty the contract");
        } catch {
            assertTrue(false, "withdrawAll must not revert for the owner with funds");
        }
    }
}

