pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 balance0, uint256 value) public {
        // Admissible domain: contract is funded with a positive balance, and the
        // requested withdrawal amount exceeds that balance.
        vm.assume(balance0 > 0);
        vm.assume(value > balance0);

        vm.deal(address(c), balance0);

        bool ok;
        try c.withdraw(value) { ok = true; } catch { ok = false; }

        // Rule: withdrawing more than the contract holds must revert for every
        // admissible input. The reference respects this; the mutant drains the
        // full balance instead and succeeds.
        assertTrue(ok == false);
    }
}

