pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 total, uint256 amount, address actor) public {
        // wide admissible domain: the contract holds `total` wei, and the owner
        // withdraws a strict PART of it (amount < total)
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        total = bound(total, 1 ether, 1000 ether);
        amount = bound(amount, 0, total - 1);

        vm.deal(address(c), total);
        assert(address(c).balance == total);

        vm.deal(actor, 1 wei);
        uint256 callerBefore = actor.balance;

        vm.prank(actor);
        c.withdraw(amount);

        // General rule: a withdraw(v) call increases the caller's balance by
        // exactly v (the requested value), nothing more.
        assertTrue(actor.balance - callerBefore == amount);
    }
}

